# 3) Redefining a base function (GradedActivity & CurvedActivity)
**What it shows:** Redefinition (non-virtual) — derived class provides a function with same signature; but called version depends on the *static* type (object vs reference/pointer). This example uses a simple graded activity and a curved activity that alters setScore behavior. See slides around the CurvedActivity example. fileciteturn0file0

```cpp
// program3_redefine_setscore.cpp
#include <iostream>
#include <iomanip>
using namespace std;

class GradedActivity {
protected:
    char letter;
    double score;
    void determineGrade() {
        if (score >= 90) letter = 'A';
        else if (score >= 80) letter = 'B';
        else if (score >= 70) letter = 'C';
        else if (score >= 60) letter = 'D';
        else letter = 'F';
    }
public:
    GradedActivity() : letter(' '), score(0.0) {}
    GradedActivity(double s) : letter(' '), score(s) { determineGrade(); }
    void setScore(double s) { score = s; determineGrade(); }
    double getScore() const { return score; }
    char getLetterGrade() const { return letter; }
};

class CurvedActivity : public GradedActivity {
protected:
    double rawScore;
    double percentage; // curve multiplier (like 1.05 gives 5% bump)
public:
    CurvedActivity() : GradedActivity(), rawScore(0.0), percentage(0.0) {}
    // Redefine setScore to apply curve
    void setScore(double s) {
        rawScore = s;
        // apply curve and then call base setScore to compute letter
        GradedActivity::setScore(rawScore * (1.0 + percentage));
    }
    void setPercentage(double p) { percentage = p; }
    double getRawScore() const { return rawScore; }
};

int main() {
    CurvedActivity exam;
    double numericScore;
    double percent;
    cout << "Enter the student's raw numeric score: ";
    if(!(cin >> numericScore)) return 0;
    cout << "Enter the curve percentage (e.g. 0.06 for 6%): ";
    cin >> percent;
    exam.setPercentage(percent);
    exam.setScore(numericScore);
    cout << fixed << setprecision(2);
    cout << "The raw score is " << exam.getRawScore() << "\n";
    cout << "The curved score is " << exam.getScore() << "\n";
    cout << "The curved grade is " << exam.getLetterGrade() << "\n";
    return 0;
}
```

Compile & run:
```
g++ -std=c++11 program3_redefine_setscore.cpp -o p3 && ./p3
```

