#include <iostream>
#include <iomanip>
using namespace std;

class GradedActivity {
protected:
    double score;
public:
    GradedActivity() : score(0.0) {}
    GradedActivity(double s) : score(s) {}
    virtual void setScore(double s) { score = s; }             // MAKE VIRTUAL
    double getScore() const { return score; }
