        if (score >= 80) return 'B';
        if (score >= 70) return 'C';
        if (score >= 60) return 'D';
        return 'F';
    }
    virtual ~GradedActivity() = default; // virtual destructor (good practice)
};

class PassFailActivity : public GradedActivity {
protected:
    double minPassingScore;
public:
    PassFailActivity(double minPass = 70.0) : GradedActivity(), minPassingScore(minPass) {}
